insert into public.content_translations (entity, entity_id, locale, field, value) values
('tour','97c63004-427b-4de7-ae84-8a95425d56a8','it','title',$j$"La Via del Fuoco: alla scoperta della Fageda d'en Jordà e di Castellfollit de la Roca"$j$::jsonb),
('tour','97c63004-427b-4de7-ae84-8a95425d56a8','it','area',$j$"La Garrotxa"$j$::jsonb),
('tour','97c63004-427b-4de7-ae84-8a95425d56a8','it','meeting_point',$j$"Estació del Nord, C/ d'Alí Bei 80, 08013 Barcellona (metro L1 Arc de Triomf). Presentarsi 15 minuti prima."$j$::jsonb),
('tour','97c63004-427b-4de7-ae84-8a95425d56a8','it','inclusions',$j$["Pullman andata e ritorno da Barcellona", "Guida accompagnatrice"]$j$::jsonb),
('tour','97c63004-427b-4de7-ae84-8a95425d56a8','it','exclusions',$j$["Cibo e bevande"]$j$::jsonb),
('tour','97c63004-427b-4de7-ae84-8a95425d56a8','it','description',$j${"type": "doc", "content": [{"type": "heading", "attrs": {"level": 3}, "content": [{"text": "🌋 Fageda d'en Jordà: un mistero geologico per il vostro gruppo", "type": "text", "marks": [{"type": "bold"}]}]}, {"type": "blockquote", "content": [{"type": "paragraph", "content": [{"text": "La faggeta della Fageda d'en Jordà non è un bosco qualunque: è una ", "type": "text"}, {"text": "zona di esplorazione geologica unica", "type": "text", "marks": [{"type": "bold"}]}, {"text": " situata su un'antica colata di lava solidificata proveniente dal vulcano Croscat. A 550 metri di altitudine, rappresenta un terreno insolito e raro nella penisola iberica. Facendo parte della comarca della Garrotxa, siamo circondati da 21 crateri vulcanici, una caratteristica che ispira l'avventura e la scoperta. Questo ambiente è stato fonte di ispirazione per artisti e storici.", "type": "text"}]}]}, {"type": "heading", "attrs": {"level": 3}, "content": [{"text": "🔥 Il vulcano di Santa Margarida: coesione nel cratere", "type": "text", "marks": [{"type": "bold"}]}]}, {"type": "blockquote", "content": [{"type": "paragraph", "content": [{"text": "In questo impressionante scenario vulcanico, spicca il ", "type": "text"}, {"text": "vulcano di Santa Margarida", "type": "text", "marks": [{"type": "bold"}]}, {"text": ". La sua eruzione ha lasciato un cratere ampio e circolare, al cui interno si trova un eremo romanico. Oltre al prato che oggi occupa il cratere, il resto del vulcano è coperto da boschi di latifoglie. Il nostro percorso di esplorazione vi porta fino all'Area di Santa Margarida (seguendo parte dell'itinerario 3), un tratto ideale per svolgere ", "type": "text"}, {"text": "attività di team building", "type": "text", "marks": [{"type": "bold"}]}, {"text": " e cogliere la vera essenza di questa zona.", "type": "text"}]}]}, {"type": "heading", "attrs": {"level": 3}, "content": [{"text": "🧱 Castellfollit de la Roca: il bastione di basalto", "type": "text", "marks": [{"type": "bold"}]}]}, {"type": "blockquote", "content": [{"type": "paragraph", "content": [{"text": "Situato sul bordo di una rupe di basalto alta 50 metri e scolpita dal fiume Fluvià, ", "type": "text"}, {"text": "Castellfollit de la Roca", "type": "text", "marks": [{"type": "bold"}]}, {"text": " è uno dei paesi più piccoli e affascinanti della provincia di Girona. Il paese poggia su due colate di lava sovrapposte che gli conferiscono una sagoma suggestiva. Il suo centro storico, costruito con pietre vulcaniche, ci riporta all'XI secolo e permette al nostro gruppo di esplorare la storia dalla via principale fino al belvedere di Josep Pla. ", "type": "text"}, {"text": "È la conclusione perfetta per una giornata di esplorazione geologica.", "type": "text", "marks": [{"type": "bold"}]}]}]}]}$j$::jsonb),
('tour','fd53a1d1-fcc4-4e2d-9f6c-8f951d8c8eaa','it','title',$j$"La Sfida dei Pirenei: alla scoperta di Queralbs e della mitica Vall de Núria"$j$::jsonb),
('tour','fd53a1d1-fcc4-4e2d-9f6c-8f951d8c8eaa','it','area',$j$"Ripollès"$j$::jsonb),
('tour','fd53a1d1-fcc4-4e2d-9f6c-8f951d8c8eaa','it','difficulty',$j$"Medio (escursione facoltativa)"$j$::jsonb),
('tour','fd53a1d1-fcc4-4e2d-9f6c-8f951d8c8eaa','it','meeting_point',$j$"Estació del Nord, C/ d'Alí Bei 80, 08013 Barcellona (metro L1 Arc de Triomf). Presentarsi 15 minuti prima."$j$::jsonb),
('tour','fd53a1d1-fcc4-4e2d-9f6c-8f951d8c8eaa','it','inclusions',$j$["Pullman andata e ritorno da Barcellona", "Guida accompagnatrice", "Biglietto andata e ritorno della ferrovia a cremagliera", "Cabinovia all'interno della Vall de Núria"]$j$::jsonb),
('tour','fd53a1d1-fcc4-4e2d-9f6c-8f951d8c8eaa','it','exclusions',$j$["Cibo e bevande"]$j$::jsonb),
('tour','fd53a1d1-fcc4-4e2d-9f6c-8f951d8c8eaa','it','description',$j${"type": "doc", "content": [{"type": "heading", "attrs": {"level": 3}, "content": [{"text": "🏔️ Queralbs: il tesoro di pietra dei Pirenei", "type": "text", "marks": [{"type": "bold"}]}]}, {"type": "blockquote", "content": [{"type": "paragraph", "content": [{"text": "Il nostro punto di partenza è ", "type": "text"}, {"text": "Queralbs", "type": "text", "marks": [{"type": "bold"}]}, {"text": ", un tesoro storico situato a 1.220 metri di altitudine nella comarca del Ripollès. Con case di pietra dai tetti di ardesia, Queralbs è uno dei paesi più pittoreschi dei Pirenei catalani. Documentato fin dall'anno 839, offre uno sguardo sulla storia locale. Qui esploreremo il suo patrimonio, in particolare la ", "type": "text"}, {"text": "Chiesa di Sant Jaume (X sec.)", "type": "text", "marks": [{"type": "bold"}]}, {"text": " e il suo municipio, per preparare il nostro gruppo alla grande salita.", "type": "text"}]}]}, {"type": "heading", "attrs": {"level": 3}, "content": [{"text": "🚠 Vall de Núria: avventura a 2.000 metri (solo in squadra!)", "type": "text", "marks": [{"type": "bold"}]}]}, {"type": "blockquote", "content": [{"type": "paragraph", "content": [{"text": "L'attività principale è la salita alla ", "type": "text"}, {"text": "Vall de Núria", "type": "text", "marks": [{"type": "bold"}]}, {"text": ", un luogo idilliaco a quasi 2.000 metri di altitudine, circondato da vette che raggiungono i 3.000 metri. Questa valle è uno dei paesaggi più emblematici e belli della Catalogna. Qui il vostro gruppo potrà dedicarsi a ogni tipo di ", "type": "text"}, {"text": "sport d'avventura, escursionismo e attività di coesione", "type": "text", "marks": [{"type": "bold"}]}, {"text": ". Oltre a visitare lo storico Santuario di Núria, questo ambiente offre l'opportunità perfetta per l'esplorazione di squadra.", "type": "text"}]}]}, {"type": "heading", "attrs": {"level": 3}, "content": [{"text": "🚂 Logistica e salita: il treno a cremagliera", "type": "text", "marks": [{"type": "bold"}]}]}, {"type": "blockquote", "content": [{"type": "paragraph", "content": [{"text": "Per salire alla valle useremo il ", "type": "text"}, {"text": "treno a cremagliera", "type": "text", "marks": [{"type": "bold"}]}, {"text": ", poiché l'accesso in auto non è consentito, il che garantisce una logistica di trasporto organizzata ed efficiente per il nostro gruppo di 55 persone. Per i più avventurosi c'è la possibilità di salire a piedi da Queralbs lungo un percorso di circa 4 ore (livello medio e 800 m di dislivello). ", "type": "text"}, {"text": "Il biglietto del treno a cremagliera e la salita in cabinovia all'interno della Vall de Núria sono inclusi nel prezzo", "type": "text", "marks": [{"type": "bold"}]}, {"text": ", così potete godervi il panorama senza pagare altro.", "type": "text"}]}]}]}$j$::jsonb),
('tour','62b03939-f84a-4a7a-908b-d2bb8dc4359d','it','title',$j$"Il Cuore Selvaggio dei Pirenei: Aigüestortes e il lago di Sant Maurici"$j$::jsonb),
('tour','62b03939-f84a-4a7a-908b-d2bb8dc4359d','it','area',$j$"Pallars"$j$::jsonb),
('tour','62b03939-f84a-4a7a-908b-d2bb8dc4359d','it','meeting_point',$j$"Estació del Nord, C/ d'Alí Bei 80, 08013 Barcellona (metro L1 Arc de Triomf). Presentarsi 15 minuti prima."$j$::jsonb),
('tour','62b03939-f84a-4a7a-908b-d2bb8dc4359d','it','inclusions',$j$["Pullman andata e ritorno da Barcellona", "Guida accompagnatrice", "Taxi 4x4 Espot – Estany de Sant Maurici"]$j$::jsonb),
('tour','62b03939-f84a-4a7a-908b-d2bb8dc4359d','it','exclusions',$j$["Cibo e bevande"]$j$::jsonb),
('tour','62b03939-f84a-4a7a-908b-d2bb8dc4359d','it','description',$j${"type": "doc", "content": [{"type": "heading", "attrs": {"level": 3}, "content": [{"text": "🏞️ Aigüestortes: l'unico parco nazionale della Catalogna", "type": "text", "marks": [{"type": "bold"}]}]}, {"type": "blockquote", "content": [{"type": "paragraph", "content": [{"text": "Tripcelona vi invita a un'avventura nel cuore dei Pirenei centrali, nel Parco Nazionale di Aigüestortes i Estany de Sant Maurici.", "type": "text", "marks": [{"type": "bold"}]}, {"text": " Dichiarato Parco Nazionale il 21 ottobre 1955, è l'unico parco nazionale della Catalogna e uno dei più emblematici della Spagna. Occupa oltre 40.000 ettari nella provincia di Lleida, estendendosi tra l'Alta Ribagorça, il Pallars Sobirà, il Pallars Jussà e la Val d'Aran.", "type": "text"}]}]}, {"type": "heading", "attrs": {"level": 3}, "content": [{"text": "💧 La famosa Via delle 'Acque Tortuose'", "type": "text", "marks": [{"type": "bold"}]}]}, {"type": "blockquote", "content": [{"type": "paragraph", "content": [{"text": "Il nome del parco, ", "type": "text"}, {"text": "\"Aigüestortes\"", "type": "text", "marks": [{"type": "bold"}]}, {"text": ", significa letteralmente ", "type": "text"}, {"text": "\"Acque Tortuose\"", "type": "text", "marks": [{"type": "bold"}]}, {"text": ", in riferimento ai numerosi fiumi, torrenti e canali che serpeggiano nelle sue valli creando paesaggi unici. Il parco è di origine glaciale e offre al vostro gruppo un'esperienza di esplorazione impareggiabile, con ", "type": "text"}, {"text": "più di 200 laghi (estanys)", "type": "text", "marks": [{"type": "bold"}]}, {"text": ", fitti boschi di abeti e faggi, e vette che superano i ", "type": "text"}, {"text": "3.000 metri", "type": "text", "marks": [{"type": "bold"}]}, {"text": ".", "type": "text"}]}]}, {"type": "heading", "attrs": {"level": 3}, "content": [{"text": "⛰️ Sant Maurici e Els Encantats: il simbolo della spedizione", "type": "text", "marks": [{"type": "bold"}]}]}, {"type": "blockquote", "content": [{"type": "paragraph", "content": [{"text": "Il luogo più iconico del parco è l' ", "type": "text"}, {"text": "Estany de Sant Maurici", "type": "text", "marks": [{"type": "bold"}]}, {"text": ". La bellezza della baia è esaltata dalla maestosa coppia degli ", "type": "text"}, {"text": "Encantats", "type": "text", "marks": [{"type": "bold"}]}, {"text": ", due montagne gemelle dalla forma appuntita che dominano il paesaggio e si trovano a ", "type": "text"}, {"text": "1.910 metri di altitudine", "type": "text", "marks": [{"type": "bold"}]}, {"text": ". In questo ambiente organizziamo percorsi escursionistici e fotografici ideali per il ", "type": "text"}, {"text": "Team Building", "type": "text", "marks": [{"type": "bold"}]}, {"text": " e l'immersione totale nella natura selvaggia dei Pirenei.", "type": "text"}]}]}]}$j$::jsonb),
('tour','201a36a8-fbee-4737-b092-2e0dd669ce90','it','title',$j$"Il Canyon del Vero: Alquézar e la Via delle Passerelle"$j$::jsonb),
('tour','201a36a8-fbee-4737-b092-2e0dd669ce90','it','area',$j$"Huesca (Aragona)"$j$::jsonb),
('tour','201a36a8-fbee-4737-b092-2e0dd669ce90','it','difficulty',$j$"Facile-moderato"$j$::jsonb),
('tour','201a36a8-fbee-4737-b092-2e0dd669ce90','it','meeting_point',$j$"Estació del Nord, C/ d'Alí Bei 80, 08013 Barcellona (metro L1 Arc de Triomf). Presentarsi 15 minuti prima."$j$::jsonb),
('tour','201a36a8-fbee-4737-b092-2e0dd669ce90','it','inclusions',$j$["Pullman andata e ritorno da Barcellona", "Guida accompagnatrice"]$j$::jsonb),
('tour','201a36a8-fbee-4737-b092-2e0dd669ce90','it','exclusions',$j$["Cibo e bevande"]$j$::jsonb),
('tour','201a36a8-fbee-4737-b092-2e0dd669ce90','it','packing_list',$j$["Scarponi da montagna", "Abbigliamento caldo"]$j$::jsonb),
('tour','201a36a8-fbee-4737-b092-2e0dd669ce90','it','description',$j${"type": "doc", "content": [{"type": "heading", "attrs": {"level": 3}, "content": [{"text": "🏰 Alquézar: il borgo medievale sospeso sul canyon", "type": "text", "marks": [{"type": "bold"}]}]}, {"type": "blockquote", "content": [{"type": "paragraph", "content": [{"text": "Attraversiamo il confine con l'Aragona per raggiungere ", "type": "text"}, {"text": "Alquézar", "type": "text", "marks": [{"type": "bold"}]}, {"text": ", nel cuore del Somontano e del ", "type": "text"}, {"text": "Parco Naturale della Sierra e dei Canyon di Guara", "type": "text", "marks": [{"type": "bold"}]}, {"text": ". Considerato uno dei borghi più belli della Spagna, Alquézar sorge su una roccia, coronato dalla sua ", "type": "text"}, {"text": "Collegiata di Santa María", "type": "text", "marks": [{"type": "bold"}]}, {"text": " e i resti del suo castello di origine musulmana. In gruppo percorreremo le sue strade acciottolate, le piazze porticate e i belvedere sul canyon prima di scendere al fiume.", "type": "text"}]}]}, {"type": "heading", "attrs": {"level": 3}, "content": [{"text": "🌉 Via delle Passerelle: camminando sul fiume Vero", "type": "text", "marks": [{"type": "bold"}]}]}, {"type": "blockquote", "content": [{"type": "paragraph", "content": [{"text": "La grande avventura della giornata è la ", "type": "text"}, {"text": "Via delle Passerelle del fiume Vero", "type": "text", "marks": [{"type": "bold"}]}, {"text": ", un percorso circolare su passerelle metalliche ancorate alle pareti del canyon, scale e ponti sospesi sopra acque turchesi. Scenderemo fino al fondo del canyon, passeremo accanto a cascate e dighe secolari e cammineremo sotto enormi ripari di roccia. È un percorso spettacolare da fare in squadra, pieno di angoli per le migliori foto di gruppo.", "type": "text"}]}]}, {"type": "heading", "attrs": {"level": 3}, "content": [{"text": "🦅 Sierra de Guara: natura selvaggia e grifoni", "type": "text", "marks": [{"type": "bold"}]}]}, {"type": "blockquote", "content": [{"type": "paragraph", "content": [{"text": "Durante il percorso è frequente vedere i ", "type": "text"}, {"text": "grifoni", "type": "text", "marks": [{"type": "bold"}]}, {"text": " che sorvolano il canyon. Faremo una sosta per il pranzo (pranzo non incluso: potete portare un picnic o mangiare nei bar e nei ristoranti del paese) e avremo del tempo libero per godere di Alquézar prima di tornare a Barcellona.", "type": "text"}]}]}, {"type": "heading", "attrs": {"level": 3}, "content": [{"text": "🚌 Logistica: una giornata intera senza pensieri", "type": "text", "marks": [{"type": "bold"}]}]}, {"type": "blockquote", "content": [{"type": "paragraph", "content": [{"text": "Partiamo in pullman dall'Estació del Nord e arriviamo ad Alquézar in circa 3 ore, con una sosta tecnica lungo il percorso. La nostra guida accompagna il gruppo per tutta la giornata. ", "type": "text"}, {"text": "In inverno, l'apertura delle passerelle dipende dal tempo e dalla portata del fiume", "type": "text", "marks": [{"type": "bold"}]}, {"text": ": se non fosse possibile percorrerle, faremo un percorso alternativo lungo i belvedere e i sentieri del canyon del Vero.", "type": "text"}]}]}, {"type": "paragraph", "content": [{"text": "Foto: FrDr, Robot8A, Mikipons, McBodes, Augustin Liviu, Alberto-g-rovi, Pedro José Ponce Asensio, Enric, LSanzSal — Wikimedia Commons (licenze CC BY / CC BY-SA).", "type": "text"}]}]}$j$::jsonb),
('tour','5132cb43-7103-49fd-b901-9fdc4ef49743','it','title',$j$"La Magia Rurale della Catalogna: gita a Rupit e Tavertet"$j$::jsonb),
('tour','5132cb43-7103-49fd-b901-9fdc4ef49743','it','area',$j$"Osona"$j$::jsonb),
('tour','5132cb43-7103-49fd-b901-9fdc4ef49743','it','meeting_point',$j$"Estació del Nord, C/ d'Alí Bei 80, 08013 Barcellona (metro L1 Arc de Triomf). Presentarsi 15 minuti prima."$j$::jsonb),
