('tour','5132cb43-7103-49fd-b901-9fdc4ef49743','it','exclusions',$j$["Cibo e bevande"]$j$::jsonb),
('tour','5132cb43-7103-49fd-b901-9fdc4ef49743','it','description',$j${"type": "doc", "content": [{"type": "heading", "attrs": {"level": 3}, "content": [{"text": "🏰 Rupit: il gioiello medievale del Collsacabra", "type": "text", "marks": [{"type": "bold"}]}]}, {"type": "blockquote", "content": [{"type": "paragraph", "content": [{"text": "La nostra esplorazione inizia a ", "type": "text"}, {"text": "Rupit", "type": "text", "marks": [{"type": "bold"}]}, {"text": ", un incantevole borgo medievale riconosciuto in tutto il mondo (ONU Turismo lo ha inserito tra i «Best Tourism Villages», i migliori borghi turistici del mondo). Camminando per Rupit, il vostro gruppo si immergerà in un ambiente naturale spettacolare in cui il tempo sembra essersi fermato. È un'esperienza di immersione culturale, con le sue stradine strette, le case di pietra e i ponti sospesi che invitano all'esplorazione storica. Rupit non è solo un luogo, è un passo indietro nella storia rurale catalana.", "type": "text"}]}]}, {"type": "heading", "attrs": {"level": 3}, "content": [{"text": "⛰️ Tavertet: il belvedere geografico sospeso", "type": "text", "marks": [{"type": "bold"}]}]}, {"type": "blockquote", "content": [{"type": "paragraph", "content": [{"text": "L'avventura raggiunge il suo culmine a ", "type": "text"}, {"text": "Tavertet", "type": "text", "marks": [{"type": "bold"}]}, {"text": ", un impressionante borgo situato in cima a ", "type": "text"}, {"text": "rupe naturale (scogliera)", "type": "text", "marks": [{"type": "bold"}]}, {"text": ". Questa posizione geografica unica rende Tavertet un belvedere ineguagliabile. Da qui il vostro gruppo godrà di ", "type": "text"}, {"text": "viste panoramiche", "type": "text", "marks": [{"type": "bold"}]}, {"text": " sugli ampi bacini di ", "type": "text"}, {"text": "Sau", "type": "text", "marks": [{"type": "bold"}]}, {"text": " e ", "type": "text"}, {"text": "Susqueda", "type": "text", "marks": [{"type": "bold"}]}, {"text": ", e potrà contemplare la maestosità della catena del ", "type": "text"}, {"text": "Montseny", "type": "text", "marks": [{"type": "bold"}]}, {"text": " all'orizzonte. Questo luogo è ideale per riflettere sulla grandezza della natura catalana e scattare splendide foto di gruppo.", "type": "text"}]}]}]}$j$::jsonb),
